package com.lonx.lyrico.remote.cloud115

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.math.BigInteger
import java.util.Base64

/**
 * Vectors generated by an independent implementation: ChenyangGao/p115client's p115rsacipher /
 * p115cipher (Python), pyca/cryptography (P-224 ECDH, AES) and python-lz4. See gen_vectors.py in the
 * scratch project. 115driver ships no m115 test vectors.
 */
class Cloud115CryptoTest {
    private fun hex(s: String): ByteArray = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    // ---- m115 ----

    /** p115rsacipher.encrypt uses an all-zero client key and padding bytes 0x02 (== Go pad byte 0x01). */
    @Test fun m115EncodeMatchesP115RsaCipher() {
        val ones: (ByteArray) -> Unit = { it.fill(1) }
        assertEquals(V.m115EncodeB64, M115.encode(V.m115EncodePlain.toByteArray(), ByteArray(16), ones))
        // multi-block (>117 bytes) input
        assertEquals(V.m115EncodeLongB64, M115.encode(V.m115EncodeLongPlain.toByteArray(), ByteArray(16), ones))
    }

    @Test fun m115DecodeXorStageMatchesP115RsaCipher() {
        assertArrayEquals(hex(V.m115DecodeXorOut), M115.decodeXor(hex(V.m115DecodeXorIn), ByteArray(16)))
    }

    @Test fun m115EncodeIsRandomizedButSizedPerRsaBlock() {
        val key = M115.generateKey()
        val a = Base64.getDecoder().decode(M115.encode(ByteArray(10), key))
        val b = Base64.getDecoder().decode(M115.encode(ByteArray(10), key))
        assertEquals(128, a.size)
        assertTrue(!a.contentEquals(b))
        assertEquals(256, Base64.getDecoder().decode(M115.encode(ByteArray(200), key)).size)
    }

    // ---- ECDH / AES / LZ4 / token ----

    @Test fun remotePublicKeyIsOnP224() {
        val p = P224.Point(
            BigInteger(1, Ec115Cipher.REMOTE_PUB.copyOfRange(0, 28)),
            BigInteger(1, Ec115Cipher.REMOTE_PUB.copyOfRange(28, 56)),
        )
        assertTrue(P224.isOnCurve(p))
        assertTrue(P224.isOnCurve(P224.G))
        // n*G = infinity
        assertEquals(null, P224.mul(P224.G, P224.N))
    }

    @Test fun ecdhMatchesPycaCryptography() {
        val c = Ec115Cipher.fromPrivate(BigInteger(V.ecPriv, 16))
        assertEquals(V.ecPubToken, Cloud115Hash.hex(c.pubKey))
        val secret = hex(V.ecSecret)
        assertArrayEquals(secret.copyOfRange(0, 16), c.key)
        assertArrayEquals(secret.copyOfRange(12, 28), c.iv)
    }

    @Test fun ecdhRandomKeysAgree() {
        val c1 = Ec115Cipher.create()
        val c2 = Ec115Cipher.create()
        assertEquals(30, c1.pubKey.size)
        assertTrue(!c1.key.contentEquals(c2.key))
    }

    private val fixed = Ec115Cipher(hex(V.aesKey), hex(V.aesIv), hex(V.aesPub))

    @Test fun aesEncryptMatchesCbcPkcs7() {
        assertEquals(V.aesEncCipher, Cloud115Hash.hex(fixed.encrypt(V.aesEncPlain.toByteArray())))
    }

    @Test fun aesDecryptWithLz4MatchesPythonLz4() {
        assertEquals(V.aesDecPlain, String(fixed.decrypt(hex(V.aesDecCipher))))
    }

    @Test fun tokenMatchesP115Cipher() {
        assertEquals(V.tokenB64, fixed.encodeToken(1700000000L, 0, 0))
        // random masks still decode to the same pubkey/timestamp (p115cipher.ecdh_decode_token)
        val t = Base64.getDecoder().decode(fixed.encodeToken(1700000000L))
        assertEquals(48, t.size)
        val r1 = t[15].toInt() and 0xff
        val r2 = t[39].toInt() and 0xff
        val pub = ByteArray(30)
        for (i in 0 until 15) pub[i] = (t[i].toInt() xor r1).toByte()
        for (i in 0 until 15) pub[15 + i] = (t[24 + i].toInt() xor r2).toByte()
        assertArrayEquals(fixed.pubKey, pub)
        var ts = 0L
        for (i in 0 until 4) ts = ts or (((t[20 + i].toInt() xor r1) and 0xff).toLong() shl (8 * i))
        assertEquals(1700000000L, ts)
    }

    @Test fun lz4HandlesMatchesAndLongLiterals() {
        // literal "abc" then match offset 3 len 9 -> "abcabcabcabc", then literal tail "xyz"
        val block = byteArrayOf(0x35, 'a'.code.toByte(), 'b'.code.toByte(), 'c'.code.toByte(), 3, 0,
            0x30, 'x'.code.toByte(), 'y'.code.toByte(), 'z'.code.toByte())
        assertEquals("abcabcabcabcxyz", String(Lz4.decompressBlock(block, 0, block.size)))
    }

    // ---- upload signatures ----

    @Test fun uploadSigAndTokenMatchP115Cipher() {
        val fileId = "DA39A3EE5E6B4B0D3255BFEF95601890AFD80709"
        assertEquals(V.sig, Cloud115Hash.uploadSignature("12345", "4B1C0FFEE", fileId, "U_1_0"))
        assertEquals(V.token, Cloud115Hash.uploadToken("12345", fileId, "1048576", "", "", "1700000000123", "27.0.5.7"))
        assertEquals(V.token2, Cloud115Hash.uploadToken("12345", fileId, "1048576", "abc", "0123ABCD", "1700000000123", "27.0.5.7"))
    }

    // ---- OSS V1 signature: vectors from Aliyun's official Python SDK (oss2 2.x, ProviderAuth) ----

    @Test fun ossSignatureMatchesAliyunOss2Sdk() {
        val secret = "OtxrzxIsfpFjA7SwPzILwy8Bw21TLhquhboDYROV"
        assertEquals(
            "fV5fq7DPwNbrrig7nvUSZIVyruI=",
            Cloud115Oss.sign(
                secret, "PUT", "ODBGOERFMDMzQTczRUY3NUE3NzA5QzdFNUYzMDQxNEM=", "text/html", "Thu, 17 Nov 2005 18:49:58 GMT",
                mapOf("X-OSS-Meta-Author" to "foo@example.com", "X-OSS-Magic" to "abracadabra"), "/oss-example/nelson",
            ),
        )
        val date = "Wed, 11 Nov 2026 07:00:00 GMT"
        val sts = mapOf("x-oss-security-token" to "STOKEN")
        assertEquals(
            "R9hdrNdfG7fTNJjeehU2MBzscW0=",
            Cloud115Oss.sign(secret, "PUT", "", "application/octet-stream", date, sts, "/oss-example/nelson?partNumber=3&uploadId=UPID"),
        )
        assertEquals(
            "4qNu/2QmcrVVOoeN/LeUwSantFg=",
            Cloud115Oss.sign(secret, "POST", "", "application/octet-stream", date, sts, "/oss-example/nelson?uploads"),
        )
    }
}
